create table "public"."quiz_questions" (
  "id"            bigint                   generated by default as identity not null,
  "quiz_id"       bigint                   not null,
  "question_text" text                     not null,
  "position"      integer                  not null,
  "created_at"    timestamp with time zone not null default now(),
  "updated_at"    timestamp with time zone not null default now(),
  constraint "quiz_questions_id_quiz_key" unique (id, quiz_id),
  constraint "quiz_questions_pkey" primary key (id),
  constraint "quiz_questions_position_check" check (("position" > 0)),
  constraint "quiz_questions_question_text_check" check (((char_length(btrim(question_text)) >= 2) AND (char_length(btrim(question_text)) <= 2000))),
  constraint "quiz_questions_quiz_id_fkey" foreign key (quiz_id) references public.quiz_lessons(id) on delete cascade,
  constraint "quiz_questions_quiz_position_key" unique (quiz_id, "position")
);

alter table "public"."quiz_questions"
  enable row level security;

grant delete, insert, maintain, references, select, trigger, truncate, update on table "public"."quiz_questions" to "postgres", "service_role";
